inline ImageData image_read_wire(){
    ImageData d;std::cin>>d.root.stage>>d.root.cell;
    for(auto* v:{&d.front16,&d.front64}){size_t n;std::cin>>n;v->resize(n);for(auto& e:*v){std::string key;std::cin>>key>>e.loc.stage>>e.loc.cell;e.key=hex64(key);}}
    for(auto& n:d.cells)std::cin>>n;
