// Bit layouts of the packed 256-bit memory rows. Words are printed MSB first,
// bit0 is the integer LSB, so every field below is a little-endian bit slice.
#include <bitset>
#include <cstdint>

// Field offsets inside one record, in the order the protocol lists them.
enum {
    OFF_TYPE = 0,      OFF_TYPE_W = 3,
    OFF_BMP = 3,       OFF_BMP_W = 22,
    OFF_BITMAP_ID = 25, OFF_BITMAP_ID_W = 16,
    OFF_NI_BASE = 41,  OFF_NI_BASE_W = 22,
    OFF_CHILD = 63,    OFF_CHILD_W = 32,
    OFF_BULK_BMP = 63, OFF_BULK_BMP_W = 64,
    OFF_BULK_BASE = 127, OFF_BULK_BASE_W = 22,
    OFF_BULK_STAGE = 149, OFF_BULK_STAGE_W = 4,
    OFF_INLINE = 25,   OFF_INLINE_W = 94,
    OFF_FRAG = 0,      OFF_FRAG_W = 64,
    OFF_LEN = 64,      OFF_LEN_W = 8,
    OFF_HOP = 72,      OFF_HOP_W = 22
};

static const uint32_t IMAGE_CELLS_MAX = 4194303u;      // 22 bit cell field
static const uint32_t IMAGE_ABSENT_CHILD = 15u << 6;   // stage15, key0, cell0
static const int IMAGE_ROW_BITS = 256;

inline uint64_t rec_get(const std::bitset<256>& word, int pos, int n) {
    uint64_t v = 0;
    for (int i = 0; i < n; ++i) {
        if (pos + i >= IMAGE_ROW_BITS) break;
        if (word.test(static_cast<size_t>(pos + i))) v |= (1ULL << i);
    }
    return v;
}

inline void rec_put(std::bitset<256>& word, int pos, int n, uint64_t v) {
    for (int i = 0; i < n; ++i) {
        if (((v >> i) & 1ULL) != 0ULL) word.set(static_cast<size_t>(pos + i));
    }
}

inline bool rec_clear(const std::bitset<256>& word, int pos, int n) {
    for (int i = 0; i < n; ++i) {
        if (pos + i >= IMAGE_ROW_BITS) break;
        if (word.test(static_cast<size_t>(pos + i))) return false;
    }
    return true;
}

inline bool image_is_half(int type) { return type == 1 || type == 4; }

inline int image_cell_size(int type) { return image_is_half(type) ? 1 : 2; }

// Total record width of a node type.
inline int image_record_bits(int type) { return image_is_half(type) ? 128 : 256; }
