std::string image_word_hex(const std::bitset<256>& bits) {
    std::string out(64, '0');
    for (int i = 0; i < 64; ++i) {
        unsigned v = 0;
        for (int b = 0; b < 4; ++b) v |= bits[4 * i + b] ? 1u << b : 0;
        out[63 - i] = "0123456789abcdef"[v];
    }
    return out;
}

std::bitset<256> image_word_from_hex(const std::string& text) {
    if (text.size() != 64) throw std::runtime_error("word length");
    std::bitset<256> out;
    for (int i = 0; i < 64; ++i) {
        char c = text[63 - i];
        unsigned v = c <= '9' ? c - '0' : c - 'a' + 10;
        if (c < '0' || (c > '9' && c < 'a') || c > 'f' || v > 15) throw std::runtime_error("word hex");
        for (int b = 0; b < 4; ++b) out[4 * i + b] = ((v >> b) & 1) != 0;
    }
    return out;
}

namespace {

const uint32_t NO_STAGE = 0xFFFFFFFFu;

struct VEdge {
    uint32_t key;
    uint32_t stage;
    uint32_t cell;
};

struct VNode {
    uint32_t stage = 0;
    uint32_t cell = 0;
    int type = 0;
    uint32_t depth = 0;
    uint32_t origin = 0;
    uint64_t rhi = 0, rlo = 0;
    uint32_t bmp = 0;
    uint32_t ni_len = 0;
    uint32_t ni_base = 0;
    uint32_t bitmap_id = 0;
    std::vector<FibPfx> own;
    std::vector<VEdge> edges;
    uint32_t size = 0;
};

uint32_t owner_min_len(uint32_t origin) { return origin == 0 ? 0u : (origin == 16 ? 17u : 65u); }
uint32_t owner_max_len(uint32_t origin) { return origin == 0 ? 16u : (origin == 16 ? 64u : 128u); }

class Validator {
public:
    explicit Validator(const ImageData& d) : d_(d) {
        owner_.resize(RAM_NUM);
        used_.resize(RAM_NUM);
    }

    bool run(Fib& out) {
        if (!shape_ok()) return false;
        for (uint32_t s = 0; s < RAM_NUM; ++s) {
            owner_[s].assign(d_.cells[s], -1);
            used_[s].assign(d_.cells[s], 0);
        }
        // Roots of the three owner groups.
        if (d_.root.stage >= 0) {
            uint32_t idx;
            if (!visit(static_cast<uint32_t>(d_.root.stage), d_.root.cell, NO_STAGE, false, 0, 0, 0, 0, idx))
                return false;
            root_idx_ = idx;
            have_root_ = true;
        }
        uint64_t prev16 = 0, prev64 = 0;
        for (size_t i = 0; i < d_.front16.size(); ++i) {
            if (i > 0 && !(d_.front16[i].key > prev16)) return false;
            if (d_.front16[i].key > 0xFFFFULL) return false;
            if (d_.front16[i].loc.stage < 0) return false;
            prev16 = d_.front16[i].key;
            uint32_t idx;
            uint64_t rhi = d_.front16[i].key << 48;
            if (!visit(static_cast<uint32_t>(d_.front16[i].loc.stage), d_.front16[i].loc.cell, NO_STAGE, false,
                       16, 16, rhi, 0, idx))
                return false;
            roots16_.push_back(std::make_pair(d_.front16[i].key, idx));
        }
        for (size_t i = 0; i < d_.front64.size(); ++i) {
            if (i > 0 && !(d_.front64[i].key > prev64)) return false;
            if (d_.front64[i].loc.stage < 0) return false;
            prev64 = d_.front64[i].key;
            uint32_t idx;
            if (!visit(static_cast<uint32_t>(d_.front64[i].loc.stage), d_.front64[i].loc.cell, NO_STAGE, false,
                       64, 64, d_.front64[i].key, 0, idx))
                return false;
            roots64_.push_back(std::make_pair(d_.front64[i].key, idx));
        }

        // Dense, non-overlapping charge of every stage.
        for (uint32_t s = 0; s < RAM_NUM; ++s) {
            for (uint32_t c = 0; c < d_.cells[s]; ++c) {
                if (!used_[s][c]) return false;
            }
            if (d_.cells[s] % 2 == 1) {
                const std::bitset<256>& w = d_.banks[s][d_.banks[s].size() - 1];
                if (!rec_clear(w, 128, 128)) return false;
            }
        }
        if (prefixes_.size() > FIB_MAX_PREFIXES) return false;

        // Distinctness and hop sanity of every represented prefix.
        for (size_t i = 0; i < prefixes_.size(); ++i) {
            const FibPfx& p = prefixes_[i];
            if (p.hop > HOP_MAX_VALUE) return false;
            uint64_t nh, nl;
            fib_normalize(p.hi, p.lo, p.len, nh, nl);
            if (nh != p.hi || nl != p.lo) return false;
            out.insert(p.hi, p.lo, p.len, p.hop);
        }
        if (out.size() != prefixes_.size()) return false;

        if (!dictionary_ok()) return false;
        if (!fronts_complete()) return false;
        if (!bmps_ok(out)) return false;
        (void)root_idx_;
        return true;
    }

private:
    bool shape_ok() {
        uint64_t rows = 0;
        for (uint32_t s = 0; s < RAM_NUM; ++s) {
            uint64_t want = (static_cast<uint64_t>(d_.cells[s]) + 1) / 2;
            if (d_.banks[s].size() != want) return false;
            if (d_.cells[s] > 2u * 65536u) return false;
            rows += want;
        }
        if (rows > 65536) return false;
        if (d_.bitmaps.size() > 8193 || d_.nexthops.size() > 8192) return false;
        for (size_t i = 0; i < d_.bitmaps.size(); ++i) {
            if (i > 0 && !(d_.bitmaps[i] > d_.bitmaps[i - 1])) return false;  // distinct, increasing
        }
        return true;
    }

    bool mark(uint32_t stage, uint32_t cell, uint32_t count, uint32_t idx) {
        if (cell + count > d_.cells[stage]) return false;
        for (uint32_t c = cell; c < cell + count; ++c) {
            if (used_[stage][c]) return false;
            used_[stage][c] = 1;
        }
        owner_[stage][cell] = static_cast<int32_t>(idx) + 1;
        return true;
    }

    bool visit(uint32_t stage, uint32_t cell, uint32_t parent_stage, bool as_bulk, uint32_t origin,
               uint32_t depth, uint64_t rhi, uint64_t rlo, uint32_t& idx_out) {
        if (stage >= RAM_NUM) return false;
        if (cell >= d_.cells[stage]) return false;
        if (as_bulk && (cell & 1u)) return false;  // bulk slots are two cells at even offsets
        const std::bitset<256>& w = d_.banks[stage][cell / 2];
        uint32_t off = (cell & 1u) ? 128 : 0;
        int type = static_cast<int>(rec_get(w, static_cast<int>(off), 3));
        if (type < 1 || type > 5) return false;
        if (!image_is_half(type) && (cell & 1u)) return false;
        if (as_bulk && image_is_half(type) && !rec_clear(w, 128, 128)) return false;  // zero padded upper half

        nodes_.push_back(VNode());
        uint32_t idx = static_cast<uint32_t>(nodes_.size() - 1);
        VNode& n = nodes_[idx];
        n.stage = stage;
        n.cell = cell;
        n.type = type;
        n.depth = depth;
        n.origin = origin;
        n.rhi = rhi;
        n.rlo = rlo;
        n.bmp = static_cast<uint32_t>(rec_get(w, static_cast<int>(off) + OFF_BMP, OFF_BMP_W));
        uint32_t charge = as_bulk ? 2u : static_cast<uint32_t>(image_cell_size(type));
        if (charge == 2u && (cell & 1u)) return false;
        if (!mark(stage, cell, charge, idx)) return false;

        bool ok = true;
        if (type == 4 || type == 5) {
            ok = decode_inline(w, static_cast<int>(off), n);
            if (ok) ok = rec_clear(w, static_cast<int>(off) + (type == 4 ? 119 : 213), type == 4 ? 9 : 43);
        } else {
            ok = decode_ni(w, static_cast<int>(off), n);
            if (ok) {
                if (type == 3) ok = decode_type3(w, static_cast<int>(off), n);
                else ok = decode_children(w, static_cast<int>(off) + OFF_CHILD, n, type == 1 ? 2 : 6);
                if (ok) {
                    int rsv = (type == 3) ? (249) : (255);
                    int rsv_w = (type == 3) ? 7 : 1;
                    ok = rec_clear(w, static_cast<int>(off) + rsv, rsv_w);
                }
            }
        }
        if (!ok) return false;

        // Own prefixes: bounds, ownership and region membership.
        uint32_t omin = owner_min_len(origin), omax = owner_max_len(origin);
        for (size_t i = 0; i < n.own.size(); ++i) {
            const FibPfx& p = n.own[i];
            if (p.len < omin || p.len > omax) return false;
            if (p.len < depth) return false;
            if (type != 4 && type != 5 && p.len > depth + 5) return false;
            uint64_t mh = fib_mask_high(p.hi, depth < 64 ? depth : 64);
            uint64_t ml = (depth <= 64) ? 0 : fib_mask_high(p.lo, depth - 64);
            uint64_t rh = fib_mask_high(rhi, depth < 64 ? depth : 64);
            uint64_t rl = (depth <= 64) ? 0 : fib_mask_high(rlo, depth - 64);
            if (mh != rh || ml != rl) return false;
            prefixes_.push_back(p);
        }

        // Children, strictly lower stages, six bits deeper.
        if (!n.edges.empty() && depth + 6 > omax) return false;
        uint32_t prev_key = 0;
        bool first_edge = true;
        uint32_t total = n.own.size();
        for (size_t i = 0; i < n.edges.size(); ++i) {
            const VEdge& e = n.edges[i];
            if (!first_edge && e.key <= prev_key) return false;
            first_edge = false;
            prev_key = e.key;
            if (e.stage >= stage) return false;  // strictly lower than the parent
            uint64_t chi = rhi, clo = rlo;
            fib_set_bits(chi, clo, depth, 6, e.key);
            uint32_t cidx;
            if (!visit(e.stage, e.cell, stage, e.bulk_child, origin, depth + 6, chi, clo, cidx)) return false;
            total += nodes_[cidx].size;
        }
        n.size = total;
        if (type == 4 && total != 1) return false;
        if (type == 5 && total != 2) return false;
        if (type != 4 && type != 5 && total < 3) return false;
        idx_out = idx;
        return true;
    }

    bool decode_inline(const std::bitset<256>& w, int off, VNode& n) {
        int count = (n.type == 5) ? 2 : 1;
        int p = off + OFF_INLINE;
        uint64_t seen_len[2];
        uint64_t seen_hi[2], seen_lo[2];
        for (int i = 0; i < count; ++i) {
            uint64_t frag = rec_get(w, p, OFF_FRAG_W); p += OFF_FRAG_W;
            uint64_t rel = rec_get(w, p, OFF_LEN_W); p += OFF_LEN_W;
            uint64_t hop = rec_get(w, p, OFF_HOP_W); p += OFF_HOP_W;
            if (hop > HOP_MAX_VALUE) return false;
            if (rel > 64) return false;
            if (n.origin == 16 && (frag >> 48) != 0) return false;  // only address bits 16..63 live here
            uint64_t len = n.origin + rel;
            if (len > 128) return false;
            uint64_t hi = n.rhi, lo = n.rlo;
            // The region above the node depth is not carried; rebuild it from the fragment.
            hi &= fib_mask_high(hi, n.depth < 64 ? n.depth : 64);
            lo = (n.depth <= 64) ? 0 : fib_mask_high(lo, n.depth - 64);
            if (n.origin == 0) { hi = frag; lo = 0; }
            else if (n.origin == 16) { hi = (n.rhi & (0xFFFFULL << 48)) | (frag >> 16); lo = 0; }
            else { hi = n.rhi; lo = frag; }
            if (i == 0) { seen_hi[i] = hi; seen_lo[i] = lo; seen_len[i] = len; }
            else {
                if (seen_hi[0] == hi && seen_lo[0] == lo && seen_len[0] == len) return false;  // distinct prefixes
            }
            FibPfx pf;
            pf.hi = hi; pf.lo = lo; pf.len = static_cast<uint32_t>(len); pf.hop = static_cast<uint32_t>(hop);
            n.own.push_back(pf);
        }
        return true;
    }

    bool decode_ni(const std::bitset<256>& w, int off, VNode& n) {
        uint64_t bid = rec_get(w, off + OFF_BITMAP_ID, OFF_BITMAP_ID_W);
        uint64_t base = rec_get(w, off + OFF_NI_BASE, OFF_NI_BASE_W);
        if (bid >= d_.bitmaps.size()) return false;
        uint64_t pattern = d_.bitmaps[bid];
        if (pattern & 1ULL) return false;  // bit0 is unused
        n.bitmap_id = static_cast<uint32_t>(bid);
        n.ni_base = static_cast<uint32_t>(base);
        n.ni_len = static_cast<uint32_t>(__builtin_popcountll(pattern));
        if (n.ni_len == 0) {
            if (n.ni_base != 0) return false;
        } else {
            if (static_cast<uint64_t>(n.ni_base) + n.ni_len > d_.nexthops.size()) return false;
        }
        uint32_t slot = 0;
        for (uint32_t pos = 1; pos < 64; ++pos) {
            if (!(pattern & (1ULL << pos))) continue;
            uint32_t l = 0;
            while ((1u << (l + 1)) <= pos) ++l;
            uint32_t v = pos - (1u << l);
            if (l > 5) return false;
            uint32_t len = n.depth + l;
            if (len > 128) return false;
            uint64_t hi = n.rhi, lo = n.rlo;
            fib_set_bits(hi, lo, n.depth, l, v);
            FibPfx p;
            p.hi = hi; p.lo = lo; p.len = len; p.hop = d_.nexthops[n.ni_base + slot];
            if (p.hop > HOP_MAX_VALUE) return false;
            n.own.push_back(p);
            ++slot;
        }
        if (slot != n.ni_len) return false;
        return true;
    }

    bool decode_children(const std::bitset<256>& w, int p, VNode& n, int slots) {
        bool absent_seen = false;
        int present = 0;
        for (int i = 0; i < slots; ++i) {
            uint64_t v = rec_get(w, p + 32 * i, 32);
            if (v == IMAGE_ABSENT_CHILD) { absent_seen = true; continue; }
            if (absent_seen) return false;  // present children come first
            uint64_t st = (v >> 6) & 0xF;
            if (st >= RAM_NUM) return false;
            VEdge e;
            e.key = static_cast<uint32_t>(v & 0x3F);
            e.stage = static_cast<uint32_t>(st);
            e.cell = static_cast<uint32_t>((v >> 10) & IMAGE_CELLS_MAX);
            e.bulk_child = false;
            n.edges.push_back(e);
            ++present;
        }
        if (slots == 2 && present > 2) return false;
        if (slots == 6 && (present < 3 || present > 6)) return false;
        return true;
    }

    bool decode_type3(const std::bitset<256>& w, int off, VNode& n) {
        uint64_t bulk = rec_get(w, off + OFF_BULK_BMP, OFF_BULK_BMP_W);
        uint64_t base = rec_get(w, off + OFF_BULK_BASE, OFF_BULK_BASE_W);
        uint64_t bstage = rec_get(w, off + OFF_BULK_STAGE, OFF_BULK_STAGE_W);
        if (bstage >= RAM_NUM) return false;
        uint32_t nb = static_cast<uint32_t>(__builtin_popcountll(bulk));
        if (nb < 4) return false;             // the rest are direct, at most three
        if (bstage >= n.stage) return false;  // bulk children live on a lower stage
        if (base % 2 != 0) return false;
        if (base + 2ULL * nb > d_.cells[bstage]) return false;
        std::vector<VEdge> direct = n.edges;  // already sorted by key
        uint32_t rank = 0;
        std::vector<VEdge> all;
        for (uint32_t pos = 0; pos < 64; ++pos) {
            if (!(bulk & (1ULL << pos))) continue;
            VEdge e;
            e.key = pos;
            e.stage = static_cast<uint32_t>(bstage);
            e.cell = static_cast<uint32_t>(base + 2ULL * rank);
            e.bulk_child = true;
            all.push_back(e);
            ++rank;
        }
        for (size_t i = 0; i < direct.size(); ++i) {
            if (bulk & (1ULL << direct[i].key)) return false;  // keys are disjoint
            all.push_back(direct[i]);
        }
        std::stable_sort(all.begin(), all.end(), [](const VEdge& a, const VEdge& b) { return a.key < b.key; });
        if (all.size() < 7 || all.size() > 64) return false;
        n.edges = all;
        return true;
    }

    bool dictionary_ok() {
        std::set<uint64_t> used_patterns;
        std::vector<std::pair<uint32_t, uint32_t> > spans;
        for (size_t i = 0; i < nodes_.size(); ++i) {
            const VNode& n = nodes_[i];
            if (n.type == 4 || n.type == 5) continue;
            if (n.bitmap_id >= d_.bitmaps.size()) return false;
            uint64_t pattern = d_.bitmaps[n.bitmap_id];
            uint32_t cnt = static_cast<uint32_t>(__builtin_popcountll(pattern & ~1ULL));
            if (cnt != n.ni_len) return false;
            used_patterns.insert(pattern);
            if (cnt > 0) spans.push_back(std::make_pair(n.ni_base, cnt));
        }
        if (used_patterns.size() != d_.bitmaps.size()) return false;  // every pattern is used
        for (size_t i = 0; i < d_.bitmaps.size(); ++i) {
            if (used_patterns.find(d_.bitmaps[i]) == used_patterns.end()) return false;
        }
        std::sort(spans.begin(), spans.end());
        uint64_t cursor = 0;
        for (size_t i = 0; i < spans.size(); ++i) {
            if (spans[i].first != cursor) return false;  // disjoint, no holes
            cursor += spans[i].second;
        }
        if (cursor != d_.nexthops.size()) return false;  // covers the complete NI vector
        return true;
    }

    bool fronts_complete() {
        std::set<uint64_t> k16, k64;
        bool any0 = false;
        for (size_t i = 0; i < prefixes_.size(); ++i) {
            const FibPfx& p = prefixes_[i];
            if (p.len <= 16) any0 = true;
            else if (p.len <= 64) k16.insert(p.hi >> 48);
            else k64.insert(p.hi);
        }
        if (any0 != have_root_) return false;
        if (roots16_.size() != k16.size()) return false;
        for (size_t i = 0; i < roots16_.size(); ++i) {
            if (k16.find(roots16_[i].first) == k16.end()) return false;
        }
        if (roots64_.size() != k64.size()) return false;
        for (size_t i = 0; i < roots64_.size(); ++i) {
            if (k64.find(roots64_[i].first) == k64.end()) return false;
        }
        return true;
    }

    bool bmps_ok(const Fib& fib) {
        for (size_t i = 0; i < nodes_.size(); ++i) {
            const VNode& n = nodes_[i];
            uint32_t want = fib.lookup_upto(n.rhi, n.rlo, n.depth);
            uint32_t field = (want == FIB_NO_HOP) ? BMP_NULL_VALUE : want;
            if (n.bmp != field) return false;
        }
        return true;
    }

    const ImageData& d_;
    std::vector<std::vector<int32_t> > owner_;
    std::vector<std::vector<uint8_t> > used_;
    std::vector<VNode> nodes_;
    std::vector<FibPfx> prefixes_;
    std::vector<std::pair<uint64_t, uint32_t> > roots16_, roots64_;
    uint32_t root_idx_ = 0;
    bool have_root_ = false;
};

}  // namespace

bool image_validate(const ImageData& d, Fib& out) {
    Validator v(d);
    return v.run(out);
}

bool MemoryImage::load(const ImageData& proposed) {
    Fib fresh;
    if (!image_validate(proposed, fresh)) return false;  // previous image is preserved
    fib_ = fresh;
    data_ = proposed;
    return true;
}

nexthop_t MemoryImage::lookup(ip6_t ip) const {
    uint32_t hop = fib_.lookup(ip.hi, ip.lo);
    return (hop == FIB_NO_HOP) ? LPM_INVALID_NH : static_cast<nexthop_t>(hop);
}
