"""Independent reference model of PROTOCOL.md (v4.0): LPM, compact image
construction with randomized-but-legal placement, and full semantic image
validation.  Used only for testing; not collected with src/."""
import random

NULL_MARK = 4194303
HOP_MAX = 4194302

# ---------- bit helpers ----------
def field(word, pos, n):
    return (word >> pos) & ((1 << n) - 1)

def put(word, pos, n, v):
    assert 0 <= v < (1 << n), (v, n)
    return word | (v << pos)

def bits(hi, lo, start, count):
    v = 0
    for i in range(count):
        b = start + i
        bit = (hi >> (63 - b)) & 1 if b < 64 else (lo >> (127 - b)) & 1
        v = (v << 1) | bit
    return v

def set_bits(hi, lo, start, count, v):
    for i in range(count):
        bit = (v >> (count - 1 - i)) & 1
        if bit:
            if start + i < 64: hi |= 1 << (63 - (start + i))
            else: lo |= 1 << (127 - (start + i))
    return hi, lo

def norm(hi, lo, length):
    if length >= 64:
        keep = 64 - (length - 64)
        return hi, (lo >> keep) << keep if keep else lo
    keep = 64 - length
    return ((hi >> keep) << keep if keep else hi), 0

# ---------- LPM model ----------
class Fib:
    def __init__(self):
        self.d = {}
    def put(self, hi, lo, length, hop):
        self.d[norm(hi, lo, length) + (length,)] = hop
    def lookup_upto(self, hi, lo, maxlen=128):
        best = None
        for (h, l, ln), hop in self.d.items():
            if ln > maxlen: continue
            if bits(hi, lo, 0, ln) == bits(h, l, 0, ln):
                if best is None or ln > best[0]: best = (ln, hop)
        return None if best is None else best[1]
    def prefixes(self):
        return sorted([(h, l, ln, hop) for (h, l, ln), hop in self.d.items()], key=lambda x: (x[2], x[0], x[1]))

# ---------- structure ----------
OWNER = {0: (0, 16), 16: (17, 64), 64: (65, 128)}

def owner_of(length):
    return 0 if length <= 16 else (16 if length <= 64 else 64)

class Node:
    __slots__ = ('origin', 'depth', 'rhi', 'rlo', 'own', 'kids', 'type', 'height', 'stage',
                 'bulk', 'bulk_stage', 'direct', 'cell', 'size')
    def __init__(self):
        self.kids = []
        self.own = []
        self.bulk = []
        self.direct = []

def build(origin, depth, rhi, rlo, pfx):
    n = Node()
    n.origin, n.depth, n.rhi, n.rlo = origin, depth, rhi, rlo
    if len(pfx) <= 2:
        n.type = 4 if len(pfx) == 1 else 5
        n.own = list(pfx)
        return n
    local, kids = [], {}
    for p in pfx:
        if p[2] <= depth + 5: local.append(p)
        else: kids.setdefault(bits(p[0], p[1], depth, 6), []).append(p)
    n.own = local
    for k in sorted(kids):
        hi, lo = set_bits(rhi, rlo, depth, 6, k)
        n.kids.append((k, build(origin, depth + 6, hi, lo, kids[k])))
    n.type = 1 if len(n.kids) <= 2 else (2 if len(n.kids) <= 6 else 3)
    return n

def calc(n, rng):
    for _, c in n.kids: calc(c, rng)
    if n.type == 3:
        k = len(n.kids)
        nd = min(3, k - 4)
        if rng is not None and k - 4 >= 0:
            nd = rng.randint(0, min(3, k - 4))
        n.direct = n.kids[:nd]
        n.bulk = n.kids[nd:]
        bs = max(c.height for _, c in n.bulk)
        if rng is not None:
            hi_lim = max([c.height for _, c in n.direct] + [bs])
            bs = rng.randint(bs, hi_lim)
        n.bulk_stage = bs
    h = 0
    for _, c in n.direct: h = max(h, c.height + 1)
    if n.type == 3 and n.bulk: h = max(h, n.bulk_stage + 1)
    n.height = h
    return n

def stages(n, stage, rng):
    if rng is None or stage > n.height:
        n.stage = stage
    else:
        n.stage = rng.randint(n.height, stage) if False else n.height
    if n.type == 3 and n.bulk:
        # bulk stage must stay strictly below the node stage
        cap = n.stage - 1
        lo = max(c.height for _, c in n.bulk)
        if lo > cap:
            n.stage = lo + 1
        n.bulk_stage = rng.randint(max(lo, 0), n.stage - 1) if rng is not None else lo
    for _, c in n.direct: stages(c, c.height if rng is None else max(c.height, rng.randint(c.height, n.stage - 1)) if n.stage > c.height else c.height, rng)
    if n.type == 3 and n.bulk:
        for _, c in n.bulk: stages(c, n.bulk_stage, rng)

def collect(n, out):
    out.append(n)
    for _, c in n.kids: collect(c, out)

def layout(nodes, rng):
    """Assign cells per stage; returns cells list."""
    units = [[] for _ in range(11)]   # list of blocks (list of nodes) needing 2 cells each
    halves = [[] for _ in range(11)]
    bulkset = set()
    for n in nodes:
        if n.type == 3 and n.bulk:
            blk = [c for _, c in n.bulk]
            for c in blk: bulkset.add(id(c))
            units[n.bulk_stage].append(blk)
    for n in nodes:
        if id(n) in bulkset: continue
        if n.type in (1, 4): halves[n.stage].append(n)
        else: units[n.stage].append([n])
    cells = [0] * 11
    for s in range(11):
        if rng: rng.shuffle(units[s]); rng.shuffle(halves[s])
        c = 0
        for blk in units[s]:
            for x in blk:
                x.cell = c; c += 2
                x.size = 2
        c = 0
        # two-cell items always start on even cells; halves pair up afterwards
        pos = 0
        for blk in units[s]:
            for x in blk:
                x.cell = pos; pos += 2
        for x in halves[s]:
            x.cell = pos; pos += 1
        cells[s] = pos
    return cells

def pattern_of(n, pfx=None):
    pat = 0
    ni = []
    for p in n.own:
        l = p[2] - n.depth
        v = bits(p[0], p[1], n.depth, l)
        pos = (1 << l) + v
        pat |= 1 << pos
        ni.append((pos, p[3]))
    ni.sort()
    return pat, [h for _, h in ni]

def build_image(prefixes, rng=None):
    """prefixes: list of (hi, lo, len, hop)."""
    g0 = [p for p in prefixes if p[2] <= 16]
    g16 = {}
    g64 = {}
    for p in prefixes:
        if owner_of(p[2]) == 16: g16.setdefault(p[0] >> 48, []).append(p)
        elif owner_of(p[2]) == 64: g64.setdefault(p[0], []).append(p)
    roots = []
    if g0: roots.append(build(0, 0, 0, 0, sorted(g0)))
    f16 = []
    for k in sorted(g16):
        r = build(16, 16, k << 48, 0, sorted(g16[k])); roots.append(r); f16.append((k, r))
    f64 = []
    for k in sorted(g64):
        r = build(64, 64, k, 0, sorted(g64[k])); roots.append(r); f64.append((k, r))
    fib = Fib()
    for p in prefixes: fib.d[(p[0], p[1], p[2])] = p[3]
    for r in roots:
        calc(r, rng)
        stages(r, r.height, rng)
    nodes = []
    for r in roots: collect(r, nodes)
    cells = layout(nodes, rng)
    pats = {}
    ni_all = []
    order = list(nodes)
    if rng: rng.shuffle(order)
    for n in nodes:
        if n.type in (4, 5):
            n.pat, n.nilist = None, None
            n.ni = None
        else:
            pat, nilist = pattern_of(n)
            n.pat, n.nilist = pat, nilist
            pats[pat] = True
    bm = sorted(pats)
    bmid = {p: i for i, p in enumerate(bm)}
    nislice = {}
    nxt = []
    for n in order:
        if n.type in (4, 5) or not n.nilist: continue
        if any(m.nilist == n.nilist and m.pat == n.pat and id(m) != id(n) and id(m) < id(n) for m in order):
            pass
        if id(n) not in nislice:
            nislice[id(n)] = len(nxt)
            nxt.extend(n.nilist)
    banks = [[0] * ((c + 1) // 2) for c in cells]
    for n in nodes:
        half = n.type in (1, 4)
        off = 0 if not half else (128 if n.cell % 2 else 0)
        w = 0
        w = put(w, 0, 3, n.type)
        bmp = fib.lookup_upto(n.rhi, n.rlo, n.depth)
        w = put(w, 3, 22, NULL_MARK if bmp is None else bmp)
        if n.type in (4, 5):
            pos = 25
            for p in n.own:
                frag = p[0] if n.origin == 0 else ((p[0] << 16) if n.origin == 16 else p[1])
                w = put(w, pos, 64, frag)
                w = put(w, pos + 64, 8, p[2] - n.origin)
                w = put(w, pos + 72, 22, p[3])
                pos += 94
        else:
            w = put(w, 25, 16, bmid[n.pat])
            w = put(w, 41, 22, nislice.get(id(n), 0))
