                bmp64 = 0
                for k, c in n.bulk: bmp64 |= 1 << k
                base = min(c.cell for _, c in n.bulk)
                w = put(w, 63, 64, bmp64)
                w = put(w, 127, 22, base)
                w = put(w, 149, 4, n.bulk_stage)
