    img = {
        'root': None,
        'front16': [],
        'front64': [],
        'cells': cells,
        'banks': [[format(x, '064x') for x in b] for b in banks],
        'bitmaps': [format(x, '016x') for x in bm],
        'nexthops': nxt,
