    for k, r in f16: img['front16'].append([format(k, '04x'), r.stage, r.cell])
    for k, r in f64: img['front64'].append([format(k, '016x'), r.stage, r.cell])
    return img

# ---------- independent validation ----------
class Bad(Exception): pass

def validate(img):
    """Return dict {(hi,lo,len):hop} when the image is fully valid, else raise Bad."""
    keys = set(img)
    if keys != set('root front16 front64 cells banks bitmaps nexthops'.split()): raise Bad('keys')
    cells = img['cells']; banks = img['banks']
    if len(cells) != 11 or len(banks) != 11: raise Bad('count')
    for s in range(11):
        if not isinstance(cells[s], int) or not 0 <= cells[s] <= 131072: raise Bad('cells')
        if len(banks[s]) != (cells[s] + 1) // 2: raise Bad('rows')
    if sum(len(b) for b in banks) > 65536: raise Bad('row bound')
    if len(img['bitmaps']) > 8193 or len(img['nexthops']) > 8192: raise Bad('side bound')
    bm = [int(x, 16) for x in img['bitmaps']]
    if any(bm[i] <= bm[i-1] for i in range(1, len(bm))): raise Bad('bitmap order')
    ni = img['nexthops']
    if any(not isinstance(x, int) or not 0 <= x <= HOP_MAX for x in ni): raise Bad('ni hop')
    word = lambda s, r: int(banks[s][r], 16)

    used_cell = [[False] * c for c in cells]
    prefixes = {}
    nodes = []   # (depth, origin, rhi, rlo, bmp, own, edges)

    def take(s, c, cnt, owner):
        if c + cnt > cells[s]: raise Bad('range')
        for x in range(c, c + cnt):
            if used_cell[s][x]: raise Bad('overlap')
            used_cell[s][x] = True

    def walk(s, c, origin, depth, rhi, rlo, parent_stage, bulk_child):
        if not 0 <= s <= 10: raise Bad('stage')
        if c >= cells[s]: raise Bad('cell')
        if bulk_child and c % 2: raise Bad('bulk align')
        off = 128 if c % 2 else 0
        w = word(s, c // 2)
        t = field(w, off, 3)
        if t not in (1, 2, 3, 4, 5): raise Bad('type')
        size = 1 if t in (1, 4) else 2
        if bulk_child: size = 2
        if size == 2 and c % 2: raise Bad('align')
        if size == 2 and field(w, 128, 128) != 0 and off == 0:
            pass
        take(s, c, size, None)
        if bulk_child and size == 2 and t in (1, 4):
            if field(w, 128, 128) != 0: raise Bad('bulk pad')
        bmp = field(w, off + 3, 22)
        omin, omax = OWNER[origin]
        own = []
        edges = []
        if t in (4, 5):
            cnt = 1 if t == 4 else 2
            pos = off + 25
            seen = set()
            for i in range(cnt):
                frag = field(w, pos, 64); pos += 64
                rl = field(w, pos, 8); pos += 8
                hop = field(w, pos, 22); pos += 22
                if hop > HOP_MAX: raise Bad('hop')
                if origin == 16 and frag >> 48: raise Bad('frag16')
                length = origin + rl
                if length > 128: raise Bad('fraglen')
                if origin == 0: hi, lo = frag, 0
                elif origin == 16: hi, lo = (rhi & (0xFFFF << 48)) | (frag >> 16), 0
                else: hi, lo = rhi, frag
                if norm(hi, lo, length) != (hi, lo): raise Bad('frag host bits')
                if bits(hi, lo, 0, depth) != bits(rhi, rlo, 0, depth): raise Bad('inline region')
                if length < depth: raise Bad('inline depth')
                if not omin <= length <= omax: raise Bad('inline owner')
                if (hi, lo, length) in seen: raise Bad('dup inline')
                seen.add((hi, lo, length))
                own.append((hi, lo, length, hop))
            rsv = 9 if t == 4 else 43
            if field(w, off + (119 if t == 4 else 213), rsv) != 0: raise Bad('reserved')
        else:
            bid = field(w, off + 25, 16)
            base = field(w, off + 41, 22)
            if bid >= len(bm): raise Bad('bitmap id')
            pat = bm[bid]
            if pat & 1: raise Bad('bit0')
            k = bin(pat).count('1')
            if k == 0:
                if base != 0: raise Bad('empty base')
            elif base + k > len(ni): raise Bad('ni range')
            slot = 0
            for p in range(1, 64):
                if not (pat >> p) & 1: continue
                l = p.bit_length() - 1
                v = p - (1 << l)
                length = depth + l
                hi, lo = set_bits(rhi, rlo, depth, l, v)
                if not omin <= length <= omax: raise Bad('ni owner')
                hop = ni[base + slot]; slot += 1
                own.append((hi, lo, length, hop))
            if slot != k: raise Bad('ni count')
            if t == 3:
                bb = field(w, off + 63, 64)
                bbase = field(w, off + 127, 22)
                bstage = field(w, off + 149, 4)
                nb = bin(bb).count('1')
