// Live FIB owner. Puts are last-write-wins on the normalized prefix, queries
// return the longest matching live prefix. The live state is fully detached
// from saved snapshots and from the loaded image.
class ScampTrieDynamic {
    friend class MemInit;

public:
    ScampTrieDynamic() {}
    ~ScampTrieDynamic() {}

    uint32_t insert_prefix(ip6_t prefix128, uint8_t len128, nexthop_t nh);
    nexthop_t lookup(ip6_t ip, uint32_t& bmp_idx, int start_layer = 129);

    // The live timing switches of the hardware model are outside scope.
    void set_insert_prefix_timing_enabled(bool enabled) { insert_timing_enabled_ = enabled; }
    bool insert_prefix_timing_enabled() const { return insert_timing_enabled_; }

    const Fib& fib() const { return fib_; }

private:
    Fib fib_;
    bool insert_timing_enabled_ = true;
};

#endif // __SCAMPTRIE_DYNAMIC_H__
#include "scamptrie_dynamic.h"

uint32_t ScampTrieDynamic::insert_prefix(ip6_t prefix128, uint8_t len128, nexthop_t nh) {
    if (len128 > 128) return SCAMPTRIE_FAIL;
    if (nh > HOP_MAX_VALUE) return SCAMPTRIE_FAIL;
    fib_.insert(prefix128.hi, prefix128.lo, len128, static_cast<uint32_t>(nh));
    return SCAMPTRIE_OK;
}

nexthop_t ScampTrieDynamic::lookup(ip6_t ip, uint32_t& bmp_idx, int start_layer) {
    bmp_idx = 0;
    uint32_t limit = (start_layer < 0 || static_cast<uint32_t>(start_layer) > 128u)
                         ? 128u
                         : static_cast<uint32_t>(start_layer);
    uint32_t hop = fib_.lookup_upto(ip.hi, ip.lo, limit);
    return (hop == FIB_NO_HOP) ? LPM_INVALID_NH : static_cast<nexthop_t>(hop);
}
