content.text:
namespace {

struct VEdge {
    uint32_t key;
    uint32_t stage;
    uint32_t cell;
    bool bulk_child = false;
};

struct VNode {
    uint32_t stage = 0;
    uint32_t cell = 0;
    int type = 0;
    uint32_t depth = 0;
    uint32_t origin = 0;
    uint64_t rhi = 0, rlo = 0;
    uint32_t bmp = 0;
    uint32_t ni_len = 0;
    uint32_t ni_base = 0;
    uint32_t bitmap_id = 0;
    std::vector<FibPfx> own;
    std::vector<VEdge> edges;
    uint32_t size = 0;
};

uint32_t owner_min_len(uint32_t origin) { return origin == 0 ? 0u : (origin == 16 ? 17u : 65u); }
uint32_t owner_max_len(uint32_t origin) { return origin == 0 ? 16u : (origin == 16 ? 64u : 128u); }

class Validator {
public:
    explicit Validator(const ImageData& d) : d_(d) {
        used_.resize(RAM_NUM);
    }

    bool run(Fib& out) {
        if (!shape_ok()) return false;
        for (uint32_t s = 0; s < RAM_NUM; ++s) used_[s].assign(d_.cells[s], 0);
        // Roots of the three owner groups.
        if (d_.root.stage >= 0) {
            uint32_t idx;
            if (!visit(static_cast<uint32_t>(d_.root.stage), d_.root.cell, false, 0, 0, 0, 0, idx))
                return false;
            have_root_ = true;
        }
        uint64_t prev16 = 0, prev64 = 0;
        for (size_t i = 0; i < d_.front16.size(); ++i) {
            if (i > 0 && !(d_.front16[i].key > prev16)) return false;
            if (d_.front16[i].key > 0xFFFFULL) return false;
            if (d_.front16[i].loc.stage < 0) return false;
            prev16 = d_.front16[i].key;
            uint32_t idx;
            uint64_t rhi = d_.front16[i].key << 48;
            if (!visit(static_cast<uint32_t>(d_.front16[i].loc.stage), d_.front16[i].loc.cell, false,
                       16, 16, rhi, 0, idx))
                return false;
            roots16_.push_back(std::make_pair(d_.front16[i].key, idx));
        }
        for (size_t i = 0; i < d_.front64.size(); ++i) {
            if (i > 0 && !(d_.front64[i].key > prev64)) return false;
            if (d_.front64[i].loc.stage < 0) return false;
            prev64 = d_.front64[i].key;
            uint32_t idx;
            if (!visit(static_cast<uint32_t>(d_.front64[i].loc.stage), d_.front64[i].loc.cell, false,
                       64, 64, d_.front64[i].key, 0, idx))
                return false;
            roots64_.push_back(std::make_pair(d_.front64[i].key, idx));
        }

        // Dense, non-overlapping charge of every stage.
        for (uint32_t s = 0; s < RAM_NUM; ++s) {
            for (uint32_t c = 0; c < d_.cells[s]; ++c) {
                if (!used_[s][c]) return false;
            }
            if (d_.cells[s] % 2 == 1) {
                const std::bitset<256>& w = d_.banks[s][d_.banks[s].size() - 1];
                if (!rec_clear(w, 128, 128)) return false;
            }
        }
        if (prefixes_.size() > FIB_MAX_PREFIXES) return false;

        // Distinctness and hop sanity of every represented prefix.
        for (size_t i = 0; i < prefixes_.size(); ++i) {
            const FibPfx& p = prefixes_[i];
            if (p.hop > HOP_MAX_VALUE) return false;
            uint64_t nh, nl;
            fib_normalize(p.hi, p.lo, p.len, nh, nl);
            if (nh != p.hi || nl != p.lo) return false;
            out.insert(p.hi, p.lo, p.len, p.hop);
        }
        if (out.size() != prefixes_.size()) return false;

        if (!dictionary_ok()) return false;
        if (!fronts_complete()) return false;
        if (!bmps_ok(out)) return false;
        return true;
    }

private:
    static bool region_match(uint64_t phi, uint64_t plo, uint64_t rhi, uint64_t rlo, uint32_t depth) {
        if (depth <= 64) return fib_mask_high(phi, depth) == fib_mask_high(rhi, depth);
        return phi == rhi && fib_mask_high(plo, depth - 64) == fib_mask_high(rlo, depth - 64);
    }
